// Lookups in the stock table (spec, Stock table). The table,
// `src/stock/table.json`, is generated by `scripts/build-stock-table.mts` from
// the stable `create-mercato-app` tarballs on npm and committed; never edit it
// by hand.
import { compareStableVersions } from './stable-version.js'
import tableJson from './stock/table.json'

/** One stable `create-mercato-app` version. */
export type StockVersion = {
  /** sha256 of the stock `template/.env.example`, a key of `files`; null when the version has none. */
  envExample: string | null
  /** Each key of the stock `.env.example` with its stock values, active and commented, in file order. Keys are sorted. */
  env: Record<string, string[]>
  /** Every credential URL string found in a text file under `template/`, sorted. */
  credentialUrls: string[]
  /** sha256 of the stock `template/README.md`; null when the version has none. */
  readme: string | null
}

export type StockTable = {
  schema: 1
  package: 'create-mercato-app'
  /** File contents by sha256, so identical files are stored once. */
  files: Record<string, string>
  /** Entries by version, ascending. */
  versions: Record<string, StockVersion>
}

/**
 * The stock entries a value is checked against. A known version uses its own
 * entry; an unknown one (newer than the tool, or a prerelease) uses every known
 * entry and reports `known: false`.
 */
export type StockMatch = {
  /** The pinned `@open-mercato/core` version, or null when it is not pinned. */
  version: string | null
  known: boolean
  entries: StockVersion[]
}

export const stockTable = tableJson as unknown as StockTable

/** The versions the table knows, ascending. */
export function stockVersions(table: StockTable = stockTable): string[] {
  return Object.keys(table.versions).sort(compareStableVersions)
}

/** The newest known version and its entry (the env diff of an unknown version compares with it). */
export function newestStock(table: StockTable = stockTable): { version: string; entry: StockVersion } {
  const versions = stockVersions(table)
  const version = versions.at(-1)
  if (version === undefined) throw new Error('The stock table has no versions.')
  return { version, entry: table.versions[version] }
}

/**
 * Looks up the stock entry for an app. `coreVersion` is the pinned
 * `@open-mercato/core` version: create-mercato-app releases in lockstep with it.
 */
export function matchStock(coreVersion: string | null, table: StockTable = stockTable): StockMatch {
  if (coreVersion !== null && Object.hasOwn(table.versions, coreVersion))
    return { version: coreVersion, known: true, entries: [table.versions[coreVersion]] }
  return { version: coreVersion, known: false, entries: stockVersions(table).map((version) => table.versions[version]) }
}

/** True when `value` is a stock value of `key` in the matched entries. */
export function isStockValue(match: StockMatch, key: string, value: string): boolean {
  return match.entries.some((entry) => Object.hasOwn(entry.env, key) && entry.env[key].includes(value))
}

/**
 * The lines of the matched version's stock `.env.example`, or null for an
 * unknown version or a version without one.
 */
export function stockEnvLines(match: StockMatch, table: StockTable = stockTable): string[] | null {
  if (!match.known) return null
  const hash = match.entries[0].envExample
  if (hash === null) return null
  return table.files[hash].split(/\r?\n/)
}

/**
 * True when `url` is a credential URL string of the stock files of any known
 * version: an app upgraded from an older version keeps its old compose URLs.
 */
export function isStockCredentialUrl(url: string, table: StockTable = stockTable): boolean {
  return Object.values(table.versions).some((entry) => entry.credentialUrls.includes(url))
}

/** True when `sha256` is the hash of the stock root README of any known version. */
export function isStockReadme(sha256: string, table: StockTable = stockTable): boolean {
  return Object.values(table.versions).some((entry) => entry.readme === sha256)
}
